import React from 'react';
import {AbsoluteFill, Easing, interpolate} from 'remotion';
import {useS, en, clamp, DUR} from './kit';

const W = 1080;
const H = 1920;

const DECISION = en('decision');
const SUENO = en('sueno');
const ORAR = en('orar');
const SEÑOR = en('senor');
const INCERTIDUMBRE = en('incertidumbre');
const PECHO = en('pecho');
const MANANA = en('manana');
const GRACIAS = en('gracias');
const CAMINO = en('camino');
const DELANTE = en('delante');
const ENTREGO = en('entrego');
const NUDO = en('nudo');
const ESTOMAGO = en('estomago');
const MIEDO = en('miedo');
const EQUIVOCARME = en('equivocarme');
const PROMESES = en('prometes');
const GUIARME = en('guiarme');
const OJO = en('ojo');
const FUERZAS = en('fuerzas');
const CREO = en('creo');
const CAMBIAR = en('cambiar');
const CONMIGO = en('conmigo');
const SALA = en('sala');
const CALMA = en('calma');
const MENTE = en('mente');
const ANSIOSA = en('ansiosa');
const ESCUCHAR = en('escuchar');
const VOZ = en('voz');
const SUAVE = en('suave');
const NOMBRE = en('nombre');
const JESUS = en('jesus');
const AMEN = en('amen');

const mezcla = (a: number[], b: number[], k: number) => `rgb(${a.map((x, i) => Math.round(x + (b[i] - x) * k)).join(',')})`;

const Cielo: React.FC<{amanecer: number}> = ({amanecer}) => {
  const arriba = mezcla([15, 20, 50], [80, 120, 180], amanecer);
  const medio = mezcla([25, 35, 75], [220, 160, 110], amanecer);
  const abajo = mezcla([35, 40, 85], [255, 220, 160], amanecer);
  return <AbsoluteFill style={{background: `linear-gradient(180deg, ${arriba} 0%, ${medio} 55%, ${abajo} 100%)`}} />;
};

const Estrellas: React.FC<{s: number; visibles: number}> = ({s, visibles}) => (
  <AbsoluteFill style={{opacity: visibles}}>
    {Array.from({length: 50}).map((_, i) => {
      const x = (i * 173) % W;
      const y = (i * 281) % 900;
      const r = 1 + (i % 3);
      const brillo = 0.4 + 0.5 * Math.abs(Math.sin(s * 0.7 + i));
      return <div key={i} style={{position: 'absolute', left: x, top: y, width: r * 2, height: r * 2, borderRadius: r, background: '#fff8e0', opacity: brillo, boxShadow: '0 0 6px #fff3c4'}} />;
    })}
  </AbsoluteFill>
);

const Sol: React.FC<{amanecer: number; s: number}> = ({amanecer, s}) => {
  const y = interpolate(amanecer, [0, 1], [1400, 800], clamp);
  const r = 140 + Math.sin(s * 1.1) * 3;
  return (
    <div style={{position: 'absolute', left: W / 2 - r * 2.5, top: y - r * 2.5, width: r * 5, height: r * 5, opacity: amanecer}}>
      <div style={{position: 'absolute', inset: 0, borderRadius: '50%', background: 'radial-gradient(circle, rgba(255,230,170,0.5) 0%, rgba(255,195,125,0.15) 35%, transparent 70%)'}} />
      <div style={{position: 'absolute', left: r * 1.5, top: r * 1.5, width: r * 2, height: r * 2, borderRadius: '50%', background: 'radial-gradient(circle at 40% 35%, #fffcf0 0%, #ffe0a0 55%, #f5b060 100%)', boxShadow: '0 0 100px 30px rgba(255,215,150,0.4)'}} />
    </div>
  );
};

const Rayos: React.FC<{fuerza: number; s: number}> = ({fuerza, s}) => (
  <AbsoluteFill style={{opacity: fuerza * 0.4, mixBlendMode: 'screen'}}>
    {Array.from({length: 7}).map((_, i) => {
      const ang = -35 + i * 10 + Math.sin(s * 0.25 + i) * 1.5;
      return <div key={i} style={{position: 'absolute', left: W / 2 - 30, top: 800, width: 60, height: 1500, transformOrigin: '50% 0%', transform: `rotate(${ang + 180}deg)`, background: 'linear-gradient(180deg, rgba(255,240,200,0.45), transparent 85%)', filter: 'blur(12px)'}} />;
    })}
  </AbsoluteFill>
);

const Colina: React.FC<{y: number; alto: number; color: [string, string]; deriva: number; borde: number}> = ({y, alto, color, deriva, borde}) => (
  <svg width={W + 200} height={alto} style={{position: 'absolute', left: -100 + deriva, top: y}} viewBox={`0 0 ${W + 200} ${alto}`}>
    <defs>
      <linearGradient id={`c${y}`} x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stopColor={color[0]} />
        <stop offset="100%" stopColor={color[1]} />
      </linearGradient>
    </defs>
    <path d={`M0 ${alto * 0.45} C ${W * 0.25} ${alto * 0.1}, ${W * 0.45} ${alto * 0.5}, ${W * 0.65} ${alto * 0.25} S ${W + 120} ${alto * 0.2}, ${W + 200} ${alto * 0.35} L ${W + 200} ${alto} L 0 ${alto} Z`} fill={`url(#c${y})`} />
    <path d={`M0 ${alto * 0.45} C ${W * 0.25} ${alto * 0.1}, ${W * 0.45} ${alto * 0.5}, ${W * 0.65} ${alto * 0.25} S ${W + 120} ${alto * 0.2}, ${W + 200} ${alto * 0.35}`} fill="none" stroke="rgba(255,230,180,0.7)" strokeWidth={3} opacity={borde} />
  </svg>
);

const Ventana: React.FC<{luz: number; s: number}> = ({luz, s}) => {
  const respira = Math.sin(s * 0.8) * 2;
  return (
    <div style={{position: 'absolute', left: 300, top: 600, width: 480, height: 600}}>
      <div style={{position: 'absolute', inset: 0, background: 'linear-gradient(135deg, #1a1d3a 0%, #101330 100%)', borderRadius: 12, boxShadow: 'inset 0 0 80px rgba(0,0,0,0.6), 0 20px 60px rgba(0,0,0,0.5)'}} />
      <div style={{position: 'absolute', left: 40, top: 40, width: 400, height: 520, border: '2px solid rgba(255,220,160,0.2)', borderRadius: 8}} />
      <div style={{position: 'absolute', left: 230, top: 20, width: 20, height: 560, background: 'rgba(255,220,160,0.1)'}} />
      <div style={{position: 'absolute', left: 20, top: 280, width: 440, height: 2, background: 'rgba(255,220,160,0.1)'}} />
      <div style={{position: 'absolute', left: 60, top: 80, width: 360, height: 180, borderRadius: 8, background: `radial-gradient(ellipse at center, rgba(255,235,180,${luz * 0.6}), transparent 70%)`, opacity: luz, filter: 'blur(20px)'}} />
      <div style={{position: 'absolute', left: 180, top: 320, width: 120, height: 160, borderRadius: 6, background: `linear-gradient(180deg, rgba(255,240,200,${luz * 0.8}), rgba(255,220,160,${luz * 0.4}))`, opacity: luz, boxShadow: `0 0 ${40 * luz}px ${10 * luz}px rgba(255,210,130,0.5)`}} />
    </div>
  );
};

const Figura: React.FC<{s: number; paz: number}> = ({s, paz}) => {
  const respira = Math.sin(s * 1.3) * 4;
  const hombros = Math.sin(s * 0.9) * 2;
  return (
    <div style={{position: 'absolute', left: 540, top: 1350 + respira, transform: `translateX(${hombros}px)`}}>
      <div style={{position: 'absolute', left: -150, top: -200, width: 300, height: 300, borderRadius: '50%', background: 'radial-gradient(circle, rgba(255,230,180,0.5), transparent 70%)', opacity: paz}} />
      <svg width={200} height={400} viewBox="0 0 200 400">
        <ellipse cx={100} cy={390} rx={70} ry={10} fill="rgba(0,0,0,0.25)" />
        <circle cx={100} cy={80} r={45} fill="#1a1d3a" />
        <path d="M30 180 Q 100 120 170 180 L 185 350 L 15 350 Z" fill="#1a1d3a" />
        <path d="M30 180 Q 100 120 170 180" fill="none" stroke="rgba(255,220,160,0.3)" strokeWidth={2} />
      </svg>
      <div style={{position: 'absolute', left: -200, top: -50, width: 180, height: 180, borderRadius: '50%', background: 'radial-gradient(circle at 30% 30%, rgba(255,240,200,0.3), transparent 60%)', opacity: paz * 0.6, filter: 'blur(10px)', transform: `rotate(${s * 5}deg)`}} />
    </div>
  );
};

const Nudo: React.FC<{s: number; suelta: number}> = ({s, suelta}) => {
  const tension = 1 - suelta;
  const x = 540 + Math.sin(s * 1.5) * 10 * tension;
  const y = 1450 + Math.cos(s * 1.2) * 8 * tension;
  const escala = 1 + 0.3 * tension;
  const rotacion = Math.sin(s * 2) * 15 * tension;
  return (
    <div style={{position: 'absolute', left: x, top: y, transform: `translate(-50%, -50%) scale(${escala}) rotate(${rotacion}deg)`, opacity: 1 - suelta * 0.8}}>
      <svg width={120} height={120} viewBox="0 0 120 120">
        <defs>
          <filter id="sombraNudo">
            <feDropShadow dx="0" dy="4" stdDeviation="6" flood-color="#000" flood-opacity="0.4"/>
          </filter>
        </defs>
        <path d="M60 10 Q 90 10, 90 40 Q 90 70, 60 70 Q 30 70, 30 40 Q 30 10, 60 10" fill="none" stroke="#c9b896" strokeWidth={8} strokeLinecap="round" filter="url(#sombraNudo)" />
        <path d="M60 10 Q 90 10, 90 40 Q 90 70, 60 70 Q 30 70, 30 40 Q 30 10, 60 10" fill="none" stroke="#8b7d5a" strokeWidth={4} strokeLinecap="round" />
        <path d="M60 25 Q 75 25, 75 40 Q 75 55, 60 55 Q 45 55, 45 40 Q 45 25, 60 25" fill="none" stroke="#e8dcc8" strokeWidth={2} strokeLinecap="round" opacity={0.6} />
      </svg>
    </div>
  );
};

const LuzParticulas: React.FC<{s: number; intensidad: number; color: string}> = ({s, intensidad, color}) => (
  <AbsoluteFill>
    {Array.from({length: 30}).map((_, i) => {
      const x = (i * 149) % W + Math.sin(s * 0.4 + i) * 40;
      const y = H - ((i * 197 + s * (12 + (i % 4) * 5)) % (H + 200));
      const r = 2 + (i % 3);
      return <div key={i} style={{position: 'absolute', left: x, top: y, width: r, height: r, borderRadius: r, background: color, opacity: 0.3 * intensidad * (0.5 + 0.5 * Math.sin(s + i)), filter: 'blur(1px)'}} />;
    })}
  </AbsoluteFill>
);

const CaminoLuz: React.FC<{s: number; aparece: number}> = ({s, aparece}) => {
  const k = aparece;
  return (
    <svg width={W} height={800} style={{position: 'absolute', left: 0, top: 1100, opacity: k}} viewBox={`0 0 ${W} 800`}>
      <defs>
        <linearGradient id="caminoLuz" x1="0" y1="1" x2="0" y2="0">
          <stop offset="0%" stopColor="rgba(255,230,170,0.6)" />
          <stop offset="100%" stopColor="rgba(255,245,220,0.2)" />
        </linearGradient>
      </defs>
      <path d="M420 800 C 480 650, 560 550, 540 450 S 560 300, 540 200 L 560 200 C 580 310, 590 400, 590 500 S 570 650, 700 800 Z" fill="url(#caminoLuz)" style={{clipPath: `inset(${(1 - k) * 100}% 0 0 0)`}} />
      {[0, 1, 2, 3, 4].map((i) => (
        <ellipse key={i} cx={540 - (i % 2 ? 80 : -80) + Math.sin(s * 0.8 + i) * 10} cy={600 - i * 100} rx={3} ry={1} fill="rgba(255,240,200,0.7)" style={{filter: 'blur(1px)'}} />
      ))}
    </svg>
  );
};

const HojasTrigo: React.FC<{s: number; deriva: number}> = ({s, deriva}) => (
  <AbsoluteFill>
    {Array.from({length: 15}).map((_, i) => {
      const x = -50 + (i * 80) + deriva * 0.5 + Math.sin(s * 0.6 + i) * 30;
      const y = 1600 + (i % 3) * 80;
      const h = 120 + (i % 4) * 40;
      const delay = i * 0.3;
      const balanceo = Math.sin(s * 1.2 + delay) * 12;
      return (
        <div key={i} style={{position: 'absolute', left: x, top: y, width: 4, height: h, transformOrigin: '50% 100%', transform: `rotate(${balanceo}deg)`, opacity: 0.6}}>
          <div style={{position: 'absolute', bottom: 0, left: -20, width: 44, height: 40, borderRadius: '50% 50% 0 0', background: 'linear-gradient(180deg, #4a5a3a, #3a4a2a)', transformOrigin: '50% 100%', transform: `rotate(${balanceo * 0.5}deg)`}} />
          <div style={{position: 'absolute', bottom: 30, left: -15, width: 34, height: 30, borderRadius: '50% 50% 0 0', background: 'linear-gradient(180deg, #5a6a4a, #4a5a3a)', transformOrigin: '50% 100%', transform: `rotate(${-balanceo * 0.3}deg)`}} />
        </div>
      );
    })}
  </AbsoluteFill>
);

export const Escena: React.FC = () => {
  const {s} = useS();

  const amanecer = interpolate(s, [MANANA - 0.2, MANANA + 3], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const luzVentana = interpolate(s, [SEÑOR, SEÑOR + 2], [0.2, 1], {...clamp, easing: Easing.out(Easing.quad)});
  const nudoSuelta = interpolate(s, [ENTREGO, ENTREGO + 4], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const pazLlega = interpolate(s, [GUIARME, GUIARME + 3], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const caminoAparece = interpolate(s, [CREO, CREO + 3], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const calmaTotal = interpolate(s, [CALMA, CALMA + 3], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const finalBrilla = interpolate(s, [JESUS, AMEN + 1], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});

  const zoom = 1.06 - 0.04 * (s / Math.max(DUR, 1)) + 0.02 * finalBrilla;
  const deriva = Math.sin(s * 0.12) * 15;

  return (
    <AbsoluteFill style={{overflow: 'hidden', backgroundColor: '#0a0c1a'}}>
      <AbsoluteFill style={{transform: `scale(${zoom}) translateX(${deriva}px)`, transformOrigin: '50% 55%'}}>
        <Cielo amanecer={amanecer} />
        <Estrellas s={s} visibles={1 - amanecer} />
        <Sol amanecer={amanecer} s={s} />
        <Rayos fuerza={amanecer + finalBrilla * 0.25} s={s} />

        <Colina y={950} alto={500} color={amanecer > 0.4 ? ['#6a5a7a', '#3a2e4a'] : ['#1a1d35', '#0d0f20']} deriva={deriva * 0.25} borde={amanecer * 0.6} />
        <Colina y={1150} alto={650} color={amanecer > 0.4 ? ['#4a456a', '#2a2540'] : ['#121530', '#080a18']} deriva={deriva * 0.5} borde={amanecer * 0.8} />

        <Ventana luz={luzVentana * (1 - amanecer * 0.4)} s={s} />

        <Figura s={s} paz={pazLlega} />

        <Nudo s={s} suelta={nudoSuelta} />

        <CaminoLuz s={s} aparece={caminoAparece} />

        <HojasTrigo s={s} deriva={deriva} />

        <LuzParticulas s={s} intensidad={amanecer + pazLlega * 0.5 + finalBrilla * 0.3} color="#ffe8b0" />
        <LuzParticulas s={s} intensidad={calmaTotal * 0.7} color="#c8e8ff" />
      </AbsoluteFill>

      <AbsoluteFill style={{background: 'radial-gradient(circle at 50% 50%, transparent 50%, rgba(5,6,18,0.6) 100%)'}} />
    </AbsoluteFill>
  );
};
